#requires -Version 5.1
<#
.SYNOPSIS
    PlayStation Browser

.DESCRIPTION
    Tiny launcher that opens a saved IP + a port you type in Chrome (app window).
    The IP is stored in a text file in AppData:
        %APPDATA%\PlayStationBrowser\ip.txt
    Type the port, press Enter (or click GO) and it opens  http://IP:PORT

    No additional files needed - everything is contained in this single script.

.NOTES
    Script by: @EODBruz (PowerShell Development)
    Version: 1.1.0
    X / Twitter: https://x.com/EODBruz
    GitHub: https://github.com/EODBruz/PlayStation-Browser

.INSTALL
    Download and run, or run straight from GitHub:
        irm https://raw.githubusercontent.com/EODBruz/PlayStation-Browser/main/PlayStationBrowser.ps1 | iex

.SECURITY WARNING
    If you downloaded this script and get a security warning when running:
    - Press "R" to Run once
    - OR right-click file -> Properties -> Check "Unblock" -> Apply
#>

# ============================================================================
# PATHS
# ============================================================================
$script:AppName     = "PlayStation Browser"
$script:InstallDir  = "$env:APPDATA\PlayStationBrowser"
$script:InstallPath = "$script:InstallDir\PlayStationBrowser.ps1"
$script:IpFile      = "$script:InstallDir\ip.txt"
$script:XUrl        = "https://x.com/EODBruz"
$script:RawUrl      = "https://raw.githubusercontent.com/EODBruz/PlayStation-Browser/main/PlayStationBrowser.ps1"
$script:RunningPath = $PSCommandPath

# ============================================================================
# EMBEDDED PLAYSTATION ICON (Base64 encoded ICO)
# ============================================================================
$script:IconBase64 = ""

function Install-AppIcon {
    try {
        if (-not (Test-Path $script:InstallDir)) {
            New-Item -ItemType Directory -Path $script:InstallDir -Force | Out-Null
        }
        $iconBytes = [Convert]::FromBase64String($script:IconBase64)

        # File name includes a hash of the icon, so a changed icon = a new path.
        # Windows caches icons by path, so this forces it to refresh.
        $md5  = [System.Security.Cryptography.MD5]::Create()
        $hash = ([BitConverter]::ToString($md5.ComputeHash($iconBytes)) -replace '-', '').Substring(0, 8)
        $iconPath = "$script:InstallDir\PlayStationBrowser_$hash.ico"

        if (-not (Test-Path $iconPath)) {
            [System.IO.File]::WriteAllBytes($iconPath, $iconBytes)
        }

        # Clean up older icon files
        Get-ChildItem -Path $script:InstallDir -Filter "PlayStationBrowser*.ico" -ErrorAction SilentlyContinue |
            Where-Object { $_.FullName -ne $iconPath } |
            Remove-Item -Force -ErrorAction SilentlyContinue

        return $iconPath
    } catch {
        return $null
    }
}

function Update-IconCache {
    # Tell Explorer that icons changed so the desktop refreshes right away
    try {
        Add-Type -Name Shell -Namespace Win32 -MemberDefinition '
        [DllImport("shell32.dll")]
        public static extern void SHChangeNotify(int wEventId, uint uFlags, IntPtr dwItem1, IntPtr dwItem2);
        ' -ErrorAction SilentlyContinue
        [Win32.Shell]::SHChangeNotify(0x08000000, 0, [IntPtr]::Zero, [IntPtr]::Zero)
    } catch {}
}

# ============================================================================
# SELF INSTALL + DESKTOP SHORTCUT
# ============================================================================
function Initialize-AppData {
    try {
        if (-not (Test-Path $script:InstallDir)) {
            New-Item -ItemType Directory -Path $script:InstallDir -Force | Out-Null
        }
    } catch {}
}

function Invoke-SelfInstall {
    # Put a copy of this script in %APPDATA%\PlayStationBrowser so the shortcut has a stable target
    try {
        Initialize-AppData
        if ($script:RunningPath -and ($script:RunningPath -ne $script:InstallPath) -and (Test-Path $script:RunningPath)) {
            # Running from a downloaded file - copy it
            Copy-Item -Path $script:RunningPath -Destination $script:InstallPath -Force -ErrorAction SilentlyContinue
        } elseif (-not $script:RunningPath) {
            # Running straight from GitHub (irm | iex) - download the file so the shortcut works
            try {
                [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
                $tmp = "$script:InstallPath.tmp"
                $wc  = New-Object System.Net.WebClient
                $wc.DownloadFile($script:RawUrl, $tmp)
                Move-Item -Path $tmp -Destination $script:InstallPath -Force
            } catch {}
        }
    } catch {}
}

function Install-DesktopShortcut {
    param([string]$IconPath)
    try {
        if (-not (Test-Path $script:InstallPath)) { return }
        $shortcutPath = [System.IO.Path]::Combine(
            [Environment]::GetFolderPath('Desktop'),
            'PlayStation Browser.lnk'
        )

        # Always refresh the shortcut so the icon is applied even if it already exists
        $wsh = New-Object -ComObject WScript.Shell
        $sc  = $wsh.CreateShortcut($shortcutPath)
        $sc.TargetPath       = "powershell.exe"
        $sc.Arguments        = "-WindowStyle Hidden -ExecutionPolicy Bypass -File `"$script:InstallPath`""
        $sc.WorkingDirectory = $script:InstallDir
        $sc.Description      = "PlayStation Browser"
        if ($IconPath -and (Test-Path $IconPath)) {
            $sc.IconLocation = "$IconPath,0"
        }
        $sc.WindowStyle      = 7  # Minimized - hides the PowerShell flash
        $sc.Save()
    } catch {}
}

# ============================================================================
# SAVED IP (txt file in AppData)
# ============================================================================
function Get-SavedIp {
    try {
        if (Test-Path $script:IpFile) {
            $raw = (Get-Content -Path $script:IpFile -Raw -ErrorAction Stop)
            if ($raw) { return $raw.Trim() }
        }
    } catch {}
    return ""
}

function Save-Ip {
    param([string]$Ip)
    try {
        Initialize-AppData
        Set-Content -Path $script:IpFile -Value $Ip -Encoding ASCII -Force
    } catch {}
}

function Test-ValidIp {
    param([string]$Ip)
    if ($Ip -notmatch '^\d{1,3}(\.\d{1,3}){3}$') { return $false }
    foreach ($octet in $Ip.Split('.')) {
        if ([int]$octet -gt 255) { return $false }
    }
    return $true
}

# ============================================================================
# CHROME / CHROMIUM BROWSER LOOKUP
# ============================================================================
function Get-BrowserPath {
    param($browserName)

    switch ($browserName) {
        "Chrome" {
            $paths = @(
                "$env:ProgramFiles\Google\Chrome\Application\chrome.exe",
                "$env:ProgramFiles (x86)\Google\Chrome\Application\chrome.exe",
                "$env:LOCALAPPDATA\Google\Chrome\Application\chrome.exe"
            )
        }
        "Edge" {
            $paths = @(
                "$env:ProgramFiles (x86)\Microsoft\Edge\Application\msedge.exe",
                "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe",
                "$env:LOCALAPPDATA\Microsoft\Edge\Application\msedge.exe"
            )
        }
        "Brave" {
            $paths = @(
                "$env:ProgramFiles\BraveSoftware\Brave-Browser\Application\brave.exe",
                "$env:ProgramFiles (x86)\BraveSoftware\Brave-Browser\Application\brave.exe",
                "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\Application\brave.exe"
            )
        }
        default { return $null }
    }

    return $paths | Where-Object { Test-Path $_ } | Select-Object -First 1
}

function Find-Browser {
    # Chrome first, then other Chromium browsers as a fallback
    foreach ($b in @("Chrome", "Edge", "Brave")) {
        $p = Get-BrowserPath $b
        if ($p) { return $p }
    }
    return $null
}

function Open-InBrowser {
    param([string]$Url)

    $browserPath = Find-Browser
    if ($browserPath) {
        $screen = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea
        $wW = 1200; $wH = 800
        $l  = [Math]::Floor(($screen.Width  - $wW) / 2)
        $t  = [Math]::Floor(($screen.Height - $wH) / 2)
        Start-Process -FilePath $browserPath -ArgumentList "--app=`"$Url`" --window-size=$wW,$wH --window-position=$l,$t"
    } else {
        Start-Process $Url   # OS default browser
    }
}

# ============================================================================
# STARTUP
# ============================================================================
Invoke-SelfInstall
Initialize-AppData
$script:IconPath = Install-AppIcon
Install-DesktopShortcut -IconPath $script:IconPath
Update-IconCache

# Hide PowerShell window
Add-Type -Name Window -Namespace Console -MemberDefinition '
[DllImport("Kernel32.dll")]
public static extern IntPtr GetConsoleWindow();
[DllImport("user32.dll")]
public static extern bool ShowWindow(IntPtr hWnd, Int32 nCmdShow);
' -ErrorAction SilentlyContinue
$consolePtr = [Console.Window]::GetConsoleWindow()
[Console.Window]::ShowWindow($consolePtr, 0) | Out-Null

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
[System.Windows.Forms.Application]::EnableVisualStyles()

# Give this app its own taskbar identity so Windows shows the PlayStation icon
# instead of grouping it under the PowerShell icon
try {
    Add-Type -Name AppId -Namespace Win32 -MemberDefinition '
    [DllImport("shell32.dll", SetLastError = true)]
    public static extern void SetCurrentProcessExplicitAppUserModelID([MarshalAs(UnmanagedType.LPWStr)] string AppID);
    ' -ErrorAction SilentlyContinue
    [Win32.AppId]::SetCurrentProcessExplicitAppUserModelID("EODBruz.PlayStationBrowser")
} catch {}

# ============================================================================
# COLOURS
# ============================================================================
$colBlue   = [System.Drawing.Color]::FromArgb(0, 112, 209)   # PlayStation blue
$colBlack  = [System.Drawing.Color]::FromArgb(0, 0, 0)
$colField  = [System.Drawing.Color]::FromArgb(24, 24, 24)
$colGrey   = [System.Drawing.Color]::FromArgb(160, 160, 160)
$colError  = [System.Drawing.Color]::FromArgb(255, 80, 80)

# ============================================================================
# MAIN WINDOW
# ============================================================================
$script:dragging = $false

$form = New-Object System.Windows.Forms.Form
$script:form = $form
$form.Text            = "PlayStation Browser"
$form.Width           = 460
$form.Height          = 220
$form.StartPosition   = "CenterScreen"
$form.FormBorderStyle = "None"
$form.BackColor       = $colBlue
$form.Padding         = New-Object System.Windows.Forms.Padding(2)
$form.KeyPreview      = $true
if ($script:IconPath -and (Test-Path $script:IconPath)) {
    try { $form.Icon = New-Object System.Drawing.Icon($script:IconPath) } catch {}
}

$mainPanel = New-Object System.Windows.Forms.Panel
$mainPanel.Dock      = [System.Windows.Forms.DockStyle]::Fill
$mainPanel.BackColor = $colBlack

# ---- Header (drag area + close button) ------------------------------------
$headerPanel = New-Object System.Windows.Forms.Panel
$headerPanel.Location  = New-Object System.Drawing.Point(0, 0)
$headerPanel.Size      = New-Object System.Drawing.Size(456, 44)
$headerPanel.BackColor = $colBlack

$titleLabel = New-Object System.Windows.Forms.Label
$titleLabel.Location  = New-Object System.Drawing.Point(0, 0)
$titleLabel.Size      = New-Object System.Drawing.Size(456, 44)
$titleLabel.Text      = "PLAYSTATION BROWSER"
$titleLabel.Font      = New-Object System.Drawing.Font("Segoe UI", 16, [System.Drawing.FontStyle]::Bold)
$titleLabel.ForeColor = $colBlue
$titleLabel.BackColor = $colBlack
$titleLabel.TextAlign = "MiddleCenter"
$headerPanel.Controls.Add($titleLabel)

$closeBtn = New-Object System.Windows.Forms.Button
$closeBtn.Location  = New-Object System.Drawing.Point(412, 8)
$closeBtn.Size      = New-Object System.Drawing.Size(32, 28)
$closeBtn.Text      = "X"
$closeBtn.FlatStyle = "Flat"
$closeBtn.BackColor = $colBlack
$closeBtn.ForeColor = $colGrey
$closeBtn.Font      = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Bold)
$closeBtn.FlatAppearance.BorderSize = 0
$closeBtn.Cursor    = [System.Windows.Forms.Cursors]::Hand
$closeBtn.TabStop   = $false
$closeBtn.Add_MouseEnter({ $this.ForeColor = [System.Drawing.Color]::White; $this.BackColor = $script:form.BackColor })
$closeBtn.Add_MouseLeave({ $this.ForeColor = [System.Drawing.Color]::FromArgb(160,160,160); $this.BackColor = [System.Drawing.Color]::FromArgb(0,0,0) })
$closeBtn.Add_Click({ $script:form.Close() })
$headerPanel.Controls.Add($closeBtn)
$closeBtn.BringToFront()

# Drag the borderless window by the header
$dragDown = {
    $script:dragging    = $true
    $script:dragCursorX = [System.Windows.Forms.Cursor]::Position.X - $script:form.Left
    $script:dragCursorY = [System.Windows.Forms.Cursor]::Position.Y - $script:form.Top
}
$dragMove = {
    if ($script:dragging) {
        $script:form.Left = [System.Windows.Forms.Cursor]::Position.X - $script:dragCursorX
        $script:form.Top  = [System.Windows.Forms.Cursor]::Position.Y - $script:dragCursorY
    }
}
$dragUp = { $script:dragging = $false }
foreach ($c in @($headerPanel, $titleLabel)) {
    $c.Add_MouseDown($dragDown)
    $c.Add_MouseMove($dragMove)
    $c.Add_MouseUp($dragUp)
}
$mainPanel.Controls.Add($headerPanel)

# ---- Labels ---------------------------------------------------------------
$ipCaption = New-Object System.Windows.Forms.Label
$ipCaption.Location  = New-Object System.Drawing.Point(28, 56)
$ipCaption.Size      = New-Object System.Drawing.Size(200, 18)
$ipCaption.Text      = "IP ADDRESS"
$ipCaption.Font      = New-Object System.Drawing.Font("Segoe UI", 8, [System.Drawing.FontStyle]::Bold)
$ipCaption.ForeColor = $colBlue
$ipCaption.BackColor = $colBlack
$mainPanel.Controls.Add($ipCaption)

$portCaption = New-Object System.Windows.Forms.Label
$portCaption.Location  = New-Object System.Drawing.Point(274, 56)
$portCaption.Size      = New-Object System.Drawing.Size(80, 18)
$portCaption.Text      = "PORT"
$portCaption.Font      = New-Object System.Drawing.Font("Segoe UI", 8, [System.Drawing.FontStyle]::Bold)
$portCaption.ForeColor = $colBlue
$portCaption.BackColor = $colBlack
$mainPanel.Controls.Add($portCaption)

# ---- IP box (prefilled from ip.txt) ---------------------------------------
$ipBox = New-Object System.Windows.Forms.TextBox
$script:ipBox = $ipBox
$ipBox.Location    = New-Object System.Drawing.Point(28, 76)
$ipBox.Size        = New-Object System.Drawing.Size(220, 30)
$ipBox.Font        = New-Object System.Drawing.Font("Consolas", 14)
$ipBox.BackColor   = $colField
$ipBox.ForeColor   = [System.Drawing.Color]::White
$ipBox.BorderStyle = "FixedSingle"
$ipBox.MaxLength   = 15
$ipBox.Text        = Get-SavedIp
$mainPanel.Controls.Add($ipBox)

$colon = New-Object System.Windows.Forms.Label
$colon.Location  = New-Object System.Drawing.Point(250, 76)
$colon.Size      = New-Object System.Drawing.Size(20, 30)
$colon.Text      = ":"
$colon.Font      = New-Object System.Drawing.Font("Consolas", 16, [System.Drawing.FontStyle]::Bold)
$colon.ForeColor = [System.Drawing.Color]::White
$colon.BackColor = $colBlack
$colon.TextAlign = "MiddleCenter"
$mainPanel.Controls.Add($colon)

# ---- Port box -------------------------------------------------------------
$portBox = New-Object System.Windows.Forms.TextBox
$script:portBox = $portBox
$portBox.Location    = New-Object System.Drawing.Point(272, 76)
$portBox.Size        = New-Object System.Drawing.Size(80, 30)
$portBox.Font        = New-Object System.Drawing.Font("Consolas", 14)
$portBox.BackColor   = $colField
$portBox.ForeColor   = [System.Drawing.Color]::White
$portBox.BorderStyle = "FixedSingle"
$portBox.MaxLength   = 5
$portBox.Add_KeyPress({
    param($sender, $e)
    # digits only (still allow backspace / ctrl keys)
    if (-not [char]::IsControl($e.KeyChar) -and -not [char]::IsDigit($e.KeyChar)) {
        $e.Handled = $true
    }
})
$mainPanel.Controls.Add($portBox)

# ---- GO button ------------------------------------------------------------
$goBtn = New-Object System.Windows.Forms.Button
$script:goBtn = $goBtn
$goBtn.Location  = New-Object System.Drawing.Point(362, 74)
$goBtn.Size      = New-Object System.Drawing.Size(68, 34)
$goBtn.Text      = "GO"
$goBtn.FlatStyle = "Flat"
$goBtn.BackColor = $colBlue
$goBtn.ForeColor = [System.Drawing.Color]::White
$goBtn.Font      = New-Object System.Drawing.Font("Segoe UI", 11, [System.Drawing.FontStyle]::Bold)
$goBtn.FlatAppearance.BorderSize = 0
$goBtn.Cursor    = [System.Windows.Forms.Cursors]::Hand
$goBtn.Add_MouseEnter({ $this.BackColor = [System.Drawing.Color]::FromArgb(30, 140, 240) })
$goBtn.Add_MouseLeave({ $this.BackColor = [System.Drawing.Color]::FromArgb(0, 112, 209) })
$mainPanel.Controls.Add($goBtn)

# ---- Status line ----------------------------------------------------------
$statusLabel = New-Object System.Windows.Forms.Label
$script:statusLabel = $statusLabel
$statusLabel.Location  = New-Object System.Drawing.Point(28, 118)
$statusLabel.Size      = New-Object System.Drawing.Size(402, 22)
$statusLabel.Text      = "Enter the port and press Enter or GO"
$statusLabel.Font      = New-Object System.Drawing.Font("Segoe UI", 9)
$statusLabel.ForeColor = $colGrey
$statusLabel.BackColor = $colBlack
$mainPanel.Controls.Add($statusLabel)

$pathLabel = New-Object System.Windows.Forms.Label
$pathLabel.Location  = New-Object System.Drawing.Point(28, 170)
$pathLabel.Size      = New-Object System.Drawing.Size(220, 34)
$pathLabel.Text      = "IP saved in:`n%APPDATA%\PlayStationBrowser\ip.txt"
$pathLabel.Font      = New-Object System.Drawing.Font("Segoe UI", 8)
$pathLabel.ForeColor = [System.Drawing.Color]::FromArgb(110, 110, 110)
$pathLabel.BackColor = $colBlack
$mainPanel.Controls.Add($pathLabel)

# ---- X / Twitter link (opens in a Chrome app window) ----------------------
$xLink = New-Object System.Windows.Forms.LinkLabel
$xLink.Location        = New-Object System.Drawing.Point(250, 178)
$xLink.Size            = New-Object System.Drawing.Size(180, 22)
$xLink.Text            = "Follow @EODBruz on X"
$xLink.Font            = New-Object System.Drawing.Font("Segoe UI", 9, [System.Drawing.FontStyle]::Bold)
$xLink.TextAlign       = "MiddleRight"
$xLink.LinkColor       = [System.Drawing.Color]::FromArgb(30, 144, 255)
$xLink.ActiveLinkColor = [System.Drawing.Color]::White
$xLink.VisitedLinkColor = [System.Drawing.Color]::FromArgb(30, 144, 255)
$xLink.LinkBehavior    = [System.Windows.Forms.LinkBehavior]::HoverUnderline
$xLink.BackColor       = $colBlack
$xLink.Cursor          = [System.Windows.Forms.Cursors]::Hand
$xLink.TabStop         = $false
$xLink.Add_LinkClicked({
    try { Open-InBrowser $script:XUrl } catch {}
})
$mainPanel.Controls.Add($xLink)

# ============================================================================
# GO ACTION
# ============================================================================
$goBtn.Add_Click({
    $ip   = $script:ipBox.Text.Trim()
    $port = $script:portBox.Text.Trim()

    if (-not (Test-ValidIp $ip)) {
        $script:statusLabel.ForeColor = [System.Drawing.Color]::FromArgb(255, 80, 80)
        $script:statusLabel.Text      = "Enter a valid IP address (example 192.168.0.1)"
        $script:ipBox.Focus()
        return
    }

    $portNum = 0
    if (-not [int]::TryParse($port, [ref]$portNum) -or $portNum -lt 1 -or $portNum -gt 65535) {
        $script:statusLabel.ForeColor = [System.Drawing.Color]::FromArgb(255, 80, 80)
        $script:statusLabel.Text      = "Enter a port number between 1 and 65535"
        $script:portBox.Focus()
        return
    }

    # Remember the IP for next time
    Save-Ip $ip

    $url = "http://${ip}:${portNum}"
    try {
        Open-InBrowser $url
        $script:statusLabel.ForeColor = [System.Drawing.Color]::FromArgb(160, 160, 160)
        $script:statusLabel.Text      = "Opened $url"
    } catch {
        $script:statusLabel.ForeColor = [System.Drawing.Color]::FromArgb(255, 80, 80)
        $script:statusLabel.Text      = "Could not open browser: $($_.Exception.Message)"
    }
})

# Enter key = GO, Esc = close
$form.AcceptButton = $goBtn
$form.Add_KeyDown({
    param($sender, $e)
    if ($e.KeyCode -eq "Escape") { $script:form.Close() }
})

$form.Controls.Add($mainPanel)

$form.Add_Shown({
    $script:form.Activate()
    # Saved IP already there -> jump straight to the port box
    if ($script:ipBox.Text.Length -gt 0) { $script:portBox.Focus() } else { $script:ipBox.Focus() }
})

$form.Add_FormClosed({
    [System.Diagnostics.Process]::GetCurrentProcess().Kill()
})

[void]$form.ShowDialog()
